using PlumePdf;
using PlumePdf.Filters.Tiff;
using Xunit;

namespace PlumePdf.Tests.Filters.Tiff;

/// <summary>
/// <see cref="TiffReader"/>/<see cref="TiffFrameDecoder"/> against real
/// libtiff-generated fixtures (libtiff 4.7.2; provenance: a 64x40 synthetic bilevel raster
/// - same source raster as <c>CcittFaxEngineTests</c> - wrapped in a minimal uncompressed
/// classic TIFF and run through <c>tiffcp -c none|packbits|lzw|zip|g3:1d|g3:2d|g4</c>, plus
/// a 2-page copy (<c>tiffcp a.tif a.tif multiframe.tif</c>), a tiled copy
/// (<c>tiffcp -t -w 32 -l 16</c>), and Pillow-generated RGB/Palette fixtures - byte-committed,
/// generated once, never regenerated by CI or hashed against a rolling tool version.
/// </summary>
public class TiffReaderTests
{
    private const int Width = 64;
    private const int Height = 40;

    private static byte[] DecodeSingleFrame(byte[] tiff)
    {
        var ifds = TiffReader.ReadIfdChain(tiff, TiffReader.DefaultMaxFrames, PdfOptions.Default, null, null);
        Assert.Single(ifds);
        var frame = TiffFrameDecoder.DecodeFrame(tiff, ifds[0], TiffFrameDecoder.DefaultMaxDecodedPixels, PdfOptions.Default, null, null);
        Assert.NotNull(frame);
        return frame!.Pixels;
    }

    [Theory]
    [InlineData(nameof(BaselineTiff))]
    [InlineData(nameof(PackBitsTiff))]
    [InlineData(nameof(LzwTiff))]
    [InlineData(nameof(ZipTiff))]
    [InlineData(nameof(G4Tiff))]
    [InlineData(nameof(G3OneDTiff))]
    [InlineData(nameof(G3TwoDTiff))]
    public void DecodeFrame_EveryCompression_MatchesSourceRaster(string fixtureName)
    {
        var tiff = fixtureName switch
        {
            nameof(BaselineTiff) => BaselineTiff,
            nameof(PackBitsTiff) => PackBitsTiff,
            nameof(LzwTiff) => LzwTiff,
            nameof(ZipTiff) => ZipTiff,
            nameof(G4Tiff) => G4Tiff,
            nameof(G3OneDTiff) => G3OneDTiff,
            nameof(G3TwoDTiff) => G3TwoDTiff,
            _ => throw new ArgumentOutOfRangeException(nameof(fixtureName)),
        };

        var pixels = DecodeSingleFrame(tiff);

        Assert.Equal(ExpectedRaster, pixels);
    }

    [Fact]
    public void ReadIfdChain_MultiFrameTiff_ReturnsBothFrames()
    {
        var ifds = TiffReader.ReadIfdChain(MultiFrameTiff, TiffReader.DefaultMaxFrames, PdfOptions.Default, null, null);
        Assert.Equal(2, ifds.Count);

        foreach (var ifd in ifds)
        {
            var frame = TiffFrameDecoder.DecodeFrame(MultiFrameTiff, ifd, TiffFrameDecoder.DefaultMaxDecodedPixels, PdfOptions.Default, null, null);
            Assert.NotNull(frame);
            Assert.Equal(ExpectedRaster, frame!.Pixels);
        }
    }

    [Fact]
    public void DecodeFrame_TiledUncompressed_MatchesSourceRaster()
    {
        // 32x16 tiles over a 64x40 image: 2 tiles across, 3 down (the last row of tiles is a
        // partial 40-16*2=8-row edge tile) - exercises the tile-to-raster stitching including
        // a non-integer-multiple edge tile.
        var pixels = DecodeSingleFrame(TiledTiff);
        Assert.Equal(ExpectedRaster, pixels);
    }

    [Fact]
    public void DecodeFrame_Rgb_MatchesSourcePixels()
    {
        var pixels = DecodeSingleFrame(RgbTiff);
        Assert.Equal(RgbExpected, pixels);
    }

    [Fact]
    public void DecodeFrame_Palette_ReturnsIndicesAndColorMap()
    {
        var ifds = TiffReader.ReadIfdChain(PaletteTiff, TiffReader.DefaultMaxFrames, PdfOptions.Default, null, null);
        var frame = TiffFrameDecoder.DecodeFrame(PaletteTiff, ifds[0], TiffFrameDecoder.DefaultMaxDecodedPixels, PdfOptions.Default, null, null);

        Assert.NotNull(frame);
        Assert.Equal(TiffPhotometric.Palette, frame!.Photometric);
        Assert.NotNull(frame.ColorMap);
        Assert.Equal(PaletteExpectedIndices, frame.Pixels);
    }

    [Fact]
    public void LooksLikeTiff_RecognizesBothByteOrders()
    {
        Assert.True(TiffReader.LooksLikeTiff([(byte)'I', (byte)'I', 42, 0, 0, 0, 0, 0]));
        Assert.True(TiffReader.LooksLikeTiff([(byte)'M', (byte)'M', 0, 42, 0, 0, 0, 0]));
        Assert.False(TiffReader.LooksLikeTiff([(byte)'P', (byte)'K', 3, 4]));
    }

    [Fact]
    public void ReadIfdChain_NotATiff_Throws()
    {
        var ex = Assert.Throws<PlumePdfException>(() => TiffReader.ReadIfdChain("not a tiff"u8.ToArray(), TiffReader.DefaultMaxFrames, PdfOptions.Default, null, null));
        Assert.Equal("PLUME3300", ex.Code);
    }

    [Fact]
    public void ReadIfdChain_SelfReferencingIfd_StopsRatherThanLoopingForever()
    {
        // Hand-crafted: a valid header pointing at an IFD whose "next IFD offset" points
        // back at itself.
        var bytes = new List<byte>();
        bytes.AddRange("II"u8.ToArray());
        bytes.AddRange(BitConverter.GetBytes((ushort)42));
        bytes.AddRange(BitConverter.GetBytes((uint)8)); // first IFD at offset 8
        var ifdOffset = bytes.Count;
        bytes.AddRange(BitConverter.GetBytes((ushort)0)); // 0 entries
        bytes.AddRange(BitConverter.GetBytes((uint)ifdOffset)); // next IFD = itself

        var diagnostics = new DiagnosticCollection();
        // The self-referencing IFD itself is perfectly valid (0 entries is a legal, if
        // useless, IFD) - the cycle guard doesn't fail the read, it just stops the chain
        // walk after that one IFD instead of looping on it forever, with a diagnostic.
        var ifds = TiffReader.ReadIfdChain(bytes.ToArray(), TiffReader.DefaultMaxFrames, PdfOptions.Default, diagnostics, null);

        Assert.Single(ifds);
        Assert.Contains(diagnostics, d => d.Code == "PLUME3302");
    }

    [Fact]
    public void ReadIfdChain_ExceedsMaxFrames_Throws()
    {
        // Three real, distinct, non-cyclic empty IFDs chained one after another - proves the
        // frame cap fires independently of the cycle guard (a strictly-forward chain with no
        // repeated offset would otherwise run past any bound with nothing to stop it).
        var bytes = new List<byte>();
        bytes.AddRange("II"u8.ToArray());
        bytes.AddRange(BitConverter.GetBytes((ushort)42));
        bytes.AddRange(BitConverter.GetBytes((uint)8));

        for (var i = 0; i < 3; i++)
        {
            var thisIfdOffset = bytes.Count;
            var nextIfdOffset = thisIfdOffset + 6;
            bytes.AddRange(BitConverter.GetBytes((ushort)0)); // 0 entries
            bytes.AddRange(BitConverter.GetBytes((uint)(i < 2 ? nextIfdOffset : 0))); // last one terminates
        }

        var ex = Assert.Throws<PlumePdfException>(() => TiffReader.ReadIfdChain(bytes.ToArray(), maxFrames: 2, PdfOptions.Default, null, null));
        Assert.Equal("PLUME3303", ex.Code);
    }

    private static readonly byte[] BaselineTiff = Convert.FromHexString(
        "");
    private static readonly byte[] G4Tiff = Convert.FromHexString(
        "");
    private static readonly byte[] G3OneDTiff = Convert.FromHexString(
        "");
    private static readonly byte[] G3TwoDTiff = Convert.FromHexString(
        "");
    private static readonly byte[] PackBitsTiff = Convert.FromHexString(
        "");
    private static readonly byte[] LzwTiff = Convert.FromHexString(
        "");
    private static readonly byte[] ZipTiff = Convert.FromHexString(
        "");
    private static readonly byte[] MultiFrameTiff = Convert.FromHexString(
        "");
    private static readonly byte[] TiledTiff = Convert.FromHexString(
        "");
    private static readonly byte[] RgbTiff = Convert.FromHexString(
        "");
    private static readonly byte[] RgbExpected = Convert.FromHexString(
        "");
    private static readonly byte[] PaletteTiff = Convert.FromHexString(
        "");
    private static readonly byte[] PaletteExpectedIndices = Convert.FromHexString(
        "");
    private static readonly byte[] ExpectedRaster = Convert.FromHexString(
        "");
}
